import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const primitiveCleanups = [];
  const loadedTextures = [];

  const surface = vec3(0.043, 0.043, 0.063);
  const ink = vec3(0.086, 0.086, 0.114);
  const paper = '#e8ecf2';
  const accent = '#ff2a38';

  const makeGradientMaterial = (topNode, bottomNode, opacity = 1) => {
    const material = new MeshBasicNodeMaterial({
      transparent: opacity < 1,
      opacity,
      depthWrite: opacity >= 1
    });
    const vertical = smoothstep(0.0, 1.0, uv().y);
    material.colorNode = mix(bottomNode, topNode, vertical);
    return material;
  };

  const backdropMaterial = makeGradientMaterial(ink, surface, 1);
  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const panelMaterial = makeGradientMaterial(ink, surface, 0.98);
  const panel = new Mesh(
    new PlaneGeometry(6.2, 4.5),
    panelMaterial
  );
  panel.position.z = -0.55;
  root.add(panel);

  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.24,
    depthWrite: false
  });
  const imagePlane = new Mesh(
    new PlaneGeometry(5.8, 4.1),
    imageMaterial
  );
  imagePlane.position.set(0.2, -0.05, -0.36);
  root.add(imagePlane);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      loadedTextures.push(texture);
      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const frameMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.9
  });

  const topAccent = new Mesh(
    new BoxGeometry(1.05, 0.035, 0.025),
    frameMaterial
  );
  topAccent.position.set(-2.18, 1.78, -0.16);
  root.add(topAccent);

  const sideAccent = new Mesh(
    new BoxGeometry(0.035, 1.05, 0.025),
    frameMaterial
  );
  sideAccent.position.set(2.76, -1.38, -0.16);
  root.add(sideAccent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 2 : 0
    });

    textObject.position.set(-2.18, 0.3, -0.08);
    root.add(textObject);
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive === 'function') {
      const result = applyPrimitive(root, primitive.params);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const cleanup of primitiveCleanups) {
      try {
        cleanup();
      } catch (_) {}
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) {
          if (entry?.dispose) entry.dispose();
        }
      } else if (material?.dispose) {
        material.dispose();
      }
    });

    for (const texture of loadedTextures) {
      if (texture?.dispose) texture.dispose();
    }
  };

  return root;
}
